"""es — sira_c."""

T = {
"sira_151": ("¿Qué tío del Profeta ﷺ abrazó el islam y fue uno de sus defensores más firmes en La Meca?", ["Hamza ibn 'Abd al-Muttalib", "Abu Lahab", "Abu Talib", "Al-'Abbas"], "Hamza, tío y hermano de leche del Profeta ﷺ, abrazó el islam en La Meca y fue llamado «el león de Allah»."),
"sira_152": ("¿En casa de quién se reunían en secreto los primeros musulmanes en La Meca?", ["En casa de al-Arqam", "En casa de Abu Bakr", "En casa de Jadicha", "En casa de Abu Talib"], "La casa de al-Arqam ibn Abi al-Arqam, en la colina de Safa, fue el primer lugar de reunión y enseñanza."),
"sira_153": ("¿Qué compañero, converso en La Meca, fue enviado después como primer maestro a Yazrib?", ["Mus'ab ibn 'Umayr", "Bilal ibn Rabah", "Jalid ibn al-Walid", "Abu Huraira"], "Mus'ab ibn 'Umayr, joven mequí de familia noble, fue enviado a Yazrib tras el pacto de 'Aqaba para enseñar el Corán."),
"sira_154": ("¿Con qué orden comienza la sura Al-Muddazzir, que inició la llamada pública?", ["«¡Tú, el envuelto en un manto! Levántate y advierte»", "«Lee, en el nombre de tu Señor»", "«Combate a los incrédulos»", "«Emigra a Medina»"], "«¡Tú, el envuelto en un manto! Levántate y advierte»."),
"sira_155": ("¿Qué aleya ordenó al Profeta ﷺ proclamar abiertamente lo que se le mandaba?", ["«Proclama, pues, lo que se te ordena»", "«Ten paciencia»", "«Recita en secreto»", "«Retírate»"], "«Proclama, pues, lo que se te ordena y apártate de los idólatras»."),
"sira_156": ("¿Dónde colgó Quraish el documento del boicot contra Banu Hashim?", ["Dentro de la Kaaba", "En la puerta de la ciudad", "En el mercado de 'Ukaz", "En la colina de Safa"], "El texto del boicot se colgó dentro de la Kaaba, hasta que el pacto se rompió y el documento fue abandonado."),
"sira_157": ("¿En el huerto de quién, en Taif, se refugió el Profeta ﷺ y recibió un racimo de uvas tras ser expulsado?", ["En el huerto de 'Utba y Shayba, donde le sirvió el esclavo 'Addas", "En casa del jefe de Taif", "En una caravana de paso", "En casa de un herrero"], "Herido y expulsado de Taif, se refugió en un huerto donde le ofrecieron uvas, servidas por un esclavo cristiano llamado 'Addas."),
"sira_158": ("¿Qué compañero, al principio feroz adversario, abrazó el islam y fue llamado «el que distingue la verdad de la falsedad»?", ["'Umar ibn al-Jattab", "Abu Sufyan", "Jalid ibn al-Walid", "'Amr ibn al-'As"], "'Umar ibn al-Jattab, hostil al principio, se convirtió en La Meca y recibió el título de al-Faruq."),
"sira_159": ("¿En casa de qué familia se alojó el Profeta ﷺ al llegar a Medina, donde se arrodilló su camella?", ["De Abu Ayyub al-Ansari", "De Sa'd ibn Mu'adh", "De Ubayy ibn Ka'b", "De Anas ibn Malik"], "La camella se arrodilló junto a la casa de Abu Ayyub al-Ansari, que hospedó al Profeta ﷺ a su llegada."),
"sira_160": ("¿Cómo se llama el cementerio de Medina donde están enterrados muchos compañeros?", ["Al-Baqi'", "Al-Mu'alla", "Al-Hiyr", "Al-Quba"], "Baqi' al-Garqad, junto a la mezquita del Profeta ﷺ, es el cementerio de Medina."),
"sira_161": ("¿De qué mezquita dice el Corán que fue «fundada sobre la piedad desde el primer día»?", ["La mezquita de Quba", "La Mezquita Sagrada", "La mezquita de Al-Aqsa", "La mezquita de Kufa"], "«Una mezquita fundada sobre la piedad desde el primer día es más digna de que ores en ella»."),
"sira_162": ("¿En qué mezquita oraba el Profeta ﷺ cuando se reveló la orden de cambiar la alquibla?", ["La mezquita de las dos alquiblas (Masyid al-Qiblatayn)", "La mezquita de Quba", "La Mezquita Sagrada", "La mezquita de Al-Aqsa"], "La orden llegó durante la oración; los fieles se volvieron hacia la Kaaba, de ahí el nombre «mezquita de las dos alquiblas»."),
"sira_163": ("¿Qué obligación se prescribió a los musulmanes en el segundo año de la Hégira?", ["El ayuno del mes de Ramadán", "La peregrinación", "La oración nocturna", "El viaje a Taif"], "El ayuno de Ramadán se hizo obligatorio en Medina, en el segundo año de la Hégira."),
"sira_164": ("¿Qué compañero vio en sueños las palabras de la llamada a la oración, adoptadas luego por el Profeta ﷺ?", ["'Abdullah ibn Zayd", "Bilal ibn Rabah", "Abu Bakr", "Mu'adh ibn Yabal"], "'Abdullah ibn Zayd relató el sueño del adán; el Profeta ﷺ lo aprobó y encargó a Bilal proclamarlo."),
"sira_165": ("¿Qué dice el Corán del puñado de tierra que el Profeta ﷺ arrojó en Badr?", ["«No fuiste tú quien arrojó cuando arrojaste, sino que fue Allah»", "«Apuntaste bien»", "«Lo llevó el viento»", "«Lo arrojaron los ángeles»"], "«No fuiste tú quien arrojó cuando arrojaste, sino que fue Allah quien arrojó»."),
"sira_166": ("¿Cómo describe el Corán el estado de algunos creyentes al salir hacia Badr?", ["Discutían sobre ello como si fueran llevados hacia la muerte", "Todos estaban impacientes", "Se negaron a partir", "Pidieron un aplazamiento"], "«Discutían contigo sobre la verdad, después de haberse hecho evidente, como si fueran llevados hacia la muerte»."),
"sira_167": ("¿Cómo recuerda el Corán a los creyentes su situación antes de la victoria?", ["Eran pocos y oprimidos en la tierra, y Allah les dio amparo y auxilio", "Eran ricos", "Eran numerosos", "Ya gobernaban"], "«Recordad cuando erais pocos y oprimidos en la tierra… Él os dio amparo y os sostuvo con Su auxilio»."),
"sira_168": ("¿Qué compañero propuso en Badr trasladar el ejército al pozo más cercano al enemigo?", ["Al-Hubab ibn al-Munzir", "Sa'd ibn Mu'adh", "Al-Miqdad", "Az-Zubayr"], "Al-Hubab ibn al-Munzir preguntó si la posición venía de la revelación o del parecer; al saber que era parecer, propuso avanzar hasta el pozo, y el Profeta ﷺ aceptó."),
"sira_169": ("¿Cuál era el nombre del aguadero junto al cual tuvo lugar la batalla de Badr?", ["Badr, un pozo en la ruta de las caravanas", "Zamzam", "Quba", "Al-Hudaybiya"], "Badr era un aguadero en la ruta de caravanas entre La Meca y Siria; la batalla tomó de él su nombre."),
"sira_170": ("¿Qué asunto relativo a los cautivos fue tratado por revelación tras Badr?", ["El rescate aceptado por los prisioneros", "El reparto del agua", "La elección del campamento", "La fecha del regreso"], "El pasaje habla de los cautivos y del rescate, y luego permite lo tomado como lícito y bueno."),
"sira_171": ("Según la sura Al 'Imran, ¿qué cambió la situación en Uhud tras un primer éxito?", ["La desobediencia y la disputa sobre la orden recibida", "El número del enemigo", "El calor", "La falta de agua"], "«…hasta que flaqueasteis, disputasteis sobre la orden y desobedecisteis»."),
"sira_172": ("¿Qué dice el Corán de quienes son matados en el camino de Allah?", ["No los creas muertos: están vivos junto a su Señor", "Duermen hasta el Último Día", "Regresan", "Son olvidados"], "«No creas que quienes han sido matados en el camino de Allah están muertos: al contrario, están vivos junto a su Señor, bien provistos»."),
"sira_173": ("¿En qué colina apostó el Profeta ﷺ a los arqueros en Uhud?", ["El monte de los Arqueros (Yabal ar-Rumat)", "El monte Safa", "El monte Zawr", "El monte Hira"], "Cincuenta arqueros fueron apostados en una colina que pasó a llamarse «el monte de los arqueros», con la orden de no abandonarla."),
"sira_174": ("¿Cómo describe la sura Al-Ahzab la prueba del asedio de Medina?", ["Las miradas se desviaron y los corazones llegaron a las gargantas", "La ciudad cayó", "Solo faltaron víveres", "El cielo se oscureció"], "«Cuando vinieron a vosotros desde arriba y desde abajo, cuando las miradas se desviaron y los corazones llegaron a las gargantas»."),
"sira_175": ("¿Cómo describe el Corán el desenlace de la batalla del Foso?", ["Allah rechazó a los coligados llenos de ira, sin que lograran bien alguno", "Una larga batalla campal", "Un tratado de paz", "Una retirada de los musulmanes"], "«Y Allah rechazó a los que no creían, llenos de ira: no lograron bien alguno, y Allah bastó a los creyentes en el combate»."),
"sira_176": ("¿Dónde se encuentra Hudaybiya, lugar del famoso tratado?", ["En el límite del recinto sagrado, al oeste de La Meca", "Cerca de Medina", "En Yemen", "En Siria"], "Hudaybiya es un lugar situado en los límites del recinto sagrado de La Meca, donde se concluyó el tratado."),
"sira_177": ("¿Qué visión del Profeta ﷺ confirma el Corán tras Hudaybiya?", ["Que entrarían seguros en la Mezquita Sagrada, con la cabeza rapada o el pelo cortado", "Que vencerían en Jaybar", "Que construirían una ciudad", "Que viajarían a Siria"], "«Allah ha cumplido la visión con que agració a Su Mensajero: entraréis seguros en la Mezquita Sagrada»."),
"sira_178": ("¿Qué recuerda la sura Al-Fath sobre las manos contenidas en La Meca?", ["Allah contuvo sus manos contra vosotros y las vuestras contra ellos en el centro de La Meca", "Ordenó combatir", "Cerró los caminos", "Envió una tormenta"], "«Y Él es quien, en el valle de La Meca, contuvo sus manos contra vosotros y las vuestras contra ellos, después de haberos dado la victoria sobre ellos»."),
"sira_179": ("¿En qué año de la Hégira tuvo lugar la expedición de Jaybar?", ["El séptimo", "El segundo", "El quinto", "El décimo"], "Jaybar tuvo lugar en el año 7 de la Hégira, el siguiente al tratado de Hudaybiya."),
"sira_180": ("¿Cómo se llama la 'umra realizada al año siguiente de Hudaybiya, según los términos del tratado?", ["'Umrat al-Qada", "Hiyyat al-Wada'", "'Umrat al-Yi'rana", "Al-Hayy al-Akbar"], "El tratado establecía que los musulmanes volverían al año siguiente; esa 'umra se llama 'umrat al-qada."),
"sira_181": ("¿Qué soberano rompió la carta del Profeta ﷺ al recibirla?", ["El rey de Persia (Cosroes)", "El Negus de Abisinia", "El gobernador de Bahréin", "El rey de Yemen"], "El Profeta ﷺ envió cartas a los soberanos vecinos; la dirigida al rey de Persia fue rota."),
"sira_182": ("¿Qué compañero llevó la carta del Profeta ﷺ al Negus de Abisinia y a otros soberanos?", ["'Amr ibn Umayya ad-Damri", "Abu Huraira", "Anas ibn Malik", "Ubayy ibn Ka'b"], "Se eligieron mensajeros entre los compañeros; 'Amr ibn Umayya ad-Damri fue enviado al Negus."),
"sira_183": ("¿En qué dirección se halla Jaybar respecto de Medina?", ["Al norte", "Al sur", "Al este", "Al oeste, junto al mar"], "Jaybar es un oasis fortificado al norte de Medina, en la ruta hacia Siria."),
"sira_184": ("¿En qué se convirtió la casa de Abu Sufyan el día de la conquista de La Meca?", ["En un lugar seguro para quien entrara en ella", "En una prisión", "En un almacén", "En una mezquita"], "El Profeta ﷺ declaró seguro a quien entrara en la Mezquita Sagrada, permaneciera en su casa o entrara en la casa de Abu Sufyan."),
"sira_185": ("¿Qué año se llama «el año de la conquista» ('am al-fath)?", ["El año 8 de la Hégira", "El año 6 de la Hégira", "El año 10 de la Hégira", "El año 2 de la Hégira"], "La Meca fue conquistada en el año 8 de la Hégira, conocido como el año de la conquista."),
"sira_186": ("¿Qué batalla siguió poco después de la conquista de La Meca, contra las tribus de Hawazin?", ["Hunayn", "Badr", "Uhud", "Jaybar"], "Hunayn tuvo lugar poco después de la conquista, en un valle entre La Meca y Taif."),
"sira_187": ("¿Qué hizo descender Allah sobre Su Mensajero ﷺ y los creyentes tras su desconcierto en Hunayn?", ["Su sosiego (sakina), y tropas que no veían", "Lluvia", "Un viento", "Un refuerzo de jinetes"], "«Luego, Allah hizo descender Su sosiego sobre Su Mensajero y sobre los creyentes, e hizo descender tropas que no veíais»."),
"sira_188": ("¿Hacia qué ciudad se dirigió el ejército musulmán tras Hunayn?", ["Taif", "Jaybar", "Tabuk", "Saná"], "Tras Hunayn los musulmanes sitiaron Taif, cuyos habitantes se habían atrincherado."),
"sira_189": ("¿A qué expedición llama el Corán «la hora de la dificultad» (sa'at al-'usra)?", ["Tabuk", "Badr", "Jaybar", "Hunayn"], "«Allah ha aceptado el arrepentimiento del Profeta, de los emigrados y de los auxiliares que le siguieron en la hora de la dificultad»."),
"sira_190": ("¿Qué dice el Corán de los tres compañeros que se quedaron atrás en Tabuk, antes de su perdón?", ["La tierra se les hizo estrecha pese a su amplitud, y luego Allah aceptó su arrepentimiento", "Fueron desterrados", "Se marcharon a Yemen", "Fueron olvidados"], "«Y a los tres que se quedaron atrás: la tierra, con toda su amplitud, se les hizo estrecha… y luego aceptó su arrepentimiento»."),
"sira_191": ("¿En qué dirección se halla Tabuk, meta de la última gran expedición?", ["Al norte, hacia la frontera de Siria", "Al sur, hacia Yemen", "Al este, hacia Irak", "Al oeste, en el mar Rojo"], "Tabuk está al norte de Medina, en la ruta de Siria; fue la última gran expedición del Profeta ﷺ."),
"sira_192": ("¿Qué compañero equipó gran parte del ejército de Tabuk con sus propios bienes?", ["'Uzman ibn 'Affan", "Sa'd ibn Abi Waqqas", "Talha ibn 'Ubaydillah", "Abu Zarr"], "'Uzman ibn 'Affan aportó una parte considerable del equipo del «ejército de la dificultad» (yaysh al-'usra)."),
"sira_193": ("¿Qué compañero fue el primero en disparar una flecha en el camino de Allah?", ["Sa'd ibn Abi Waqqas", "Az-Zubayr ibn al-'Awwam", "Talha ibn 'Ubaydillah", "Abu 'Ubayda"], "Sa'd ibn Abi Waqqas, de los primerísimos musulmanes, es conocido como el primero en disparar una flecha en el camino de Allah."),
"sira_194": ("¿Qué compañero es llamado «el discípulo (hawari) del Mensajero de Allah ﷺ»?", ["Az-Zubayr ibn al-'Awwam", "Abu Huraira", "Salman al-Farisi", "Bilal"], "Az-Zubayr ibn al-'Awwam, primo del Profeta ﷺ, fue llamado su hawari, su apoyo cercano."),
"sira_195": ("¿A qué compañero se le confió el conocimiento de los hipócritas, por lo que fue llamado «el guardián del secreto»?", ["Huzayfa ibn al-Yaman", "Abu Musa al-Ash'ari", "'Ammar ibn Yasir", "Abu ad-Darda"], "Huzayfa ibn al-Yaman es conocido como «sahib as-sirr», aquel a quien el Profeta ﷺ confió lo que sabía de los hipócritas."),
"sira_196": ("¿De qué tierra venía Salman, llamado «al-Farisi», que propuso el foso?", ["De Persia", "De Yemen", "De Abisinia", "De Bizancio"], "Salman, de origen persa, buscó largamente la verdad antes de unirse al Profeta ﷺ en Medina."),
"sira_197": ("¿Qué mujer, madre de Anas ibn Malik, ofreció al Profeta ﷺ el servicio de su hijo?", ["Umm Sulaym", "Umm Salama", "Umm Ayman", "Umm Habiba"], "Umm Sulaym, de los ansar, presentó a su hijo Anas al Profeta ﷺ para servirle cuando llegó a Medina."),
"sira_198": ("¿Qué esposa del Profeta ﷺ fue conocida por su gran saber y transmitió numerosos hadices?", ["'Aisha", "Sawda", "Yuwayriya", "Maymuna"], "'Aisha, hija de Abu Bakr, es una de las mayores transmisoras de hadices y una referencia en ciencia religiosa."),
"sira_199": ("¿Qué esposa del Profeta ﷺ era prima suya y su matrimonio se menciona en la sura Al-Ahzab?", ["Zaynab bint Yahsh", "Hafsa", "Umm Salama", "Safiyya"], "El matrimonio con Zaynab bint Yahsh se menciona en la sura Al-Ahzab (33:37)."),
"sira_200": ("¿Qué esposa del Profeta ﷺ aconsejó lo que desbloqueó la crisis de Hudaybiya?", ["Umm Salama", "'Aisha", "Hafsa", "Zaynab bint Yahsh"], "Umm Salama aconsejó al Profeta ﷺ salir y realizar él mismo el sacrificio y el rasurado: los compañeros lo siguieron de inmediato."),
"sira_201": ("¿Cuál es el nombre completo del Profeta ﷺ, hasta su abuelo?", ["Muhammad ibn 'Abdillah ibn 'Abd al-Muttalib", "Muhammad ibn Abi Talib", "Muhammad ibn al-'Abbas", "Muhammad ibn Hashim"], "Es Muhammad, hijo de 'Abdullah, hijo de 'Abd al-Muttalib, de la tribu de Quraish."),
"sira_202": ("¿Qué otro nombre del Profeta ﷺ, mencionado en el Corán por 'Isa, significa «el más digno de alabanza»?", ["Ahmad", "Al-Mustafa", "Al-Amin", "Abu-l-Qasim"], "'Isa anunció un mensajero que vendría tras él «cuyo nombre es Ahmad» (Corán 61:6)."),
"sira_203": ("¿Cuánto duró la revelación del Corán al Profeta ﷺ?", ["Unos veintitrés años", "Diez años", "Cuarenta años", "Una sola noche"], "La revelación se extendió unos veintitrés años: trece en La Meca y diez en Medina."),
"sira_204": ("¿Qué compañero fue el primer hombre libre y adulto en abrazar el islam?", ["Abu Bakr as-Siddiq", "'Umar ibn al-Jattab", "'Uzman ibn 'Affan", "Sa'd ibn Abi Waqqas"], "Entre los hombres libres y adultos, Abu Bakr fue el primero en responder a la llamada del Profeta ﷺ."),
"sira_205": ("¿Qué niño fue el primero en abrazar el islam?", ["'Ali ibn Abi Talib", "Anas ibn Malik", "Usama ibn Zayd", "'Abdullah ibn 'Umar"], "'Ali ibn Abi Talib, criado en la casa del Profeta ﷺ, fue el primero de los niños en creer."),
"sira_206": ("¿Qué liberto del Profeta ﷺ fue el primero de los libertos en abrazar el islam?", ["Zayd ibn Hariza", "Bilal ibn Rabah", "Suhayb ar-Rumi", "Salman al-Farisi"], "Zayd ibn Hariza, liberado y criado como un hijo por el Profeta ﷺ, fue el primero de los libertos en creer."),
"sira_207": ("¿Qué aleya puso fin a la adopción legal, diciendo que el Profeta ﷺ no es padre de ninguno de sus hombres?", ["«Muhammad no es padre de ninguno de vuestros hombres, sino el Mensajero de Allah y el sello de los profetas»", "«Llamadlos por sus padres»", "«Los lazos de sangre prevalecen»", "«No adoptéis»"], "«Muhammad no es padre de ninguno de vuestros hombres, sino el Mensajero de Allah y el último de los profetas»."),
"sira_208": ("¿Qué día de la semana se reúnen los musulmanes para la oración comunitaria instituida en Medina?", ["El viernes", "El sábado", "El domingo", "El lunes"], "La oración del viernes (al-yumu'a) se instituyó en Medina y reúne a la comunidad cada semana."),
"sira_209": ("¿Qué compañero dirigió la oración durante la última enfermedad del Profeta ﷺ, por orden suya?", ["Abu Bakr as-Siddiq", "'Umar ibn al-Jattab", "'Ali ibn Abi Talib", "Bilal"], "El Profeta ﷺ ordenó que Abu Bakr dirigiera la oración durante su enfermedad; los compañeros lo vieron como una señal."),
"sira_210": ("¿Qué califa fue herido de muerte mientras dirigía la oración del alba?", ["'Umar ibn al-Jattab", "Abu Bakr", "'Ali ibn Abi Talib", "Mu'awiya"], "'Umar ibn al-Jattab fue herido durante la oración del fayr en Medina y murió de sus heridas."),
"sira_211": ("¿Cuánto duró el califato de Abu Bakr?", ["Unos dos años", "Diez años", "Veinte años", "Treinta años"], "Abu Bakr gobernó unos dos años antes de su muerte, y 'Umar le sucedió."),
"sira_212": ("¿Contra qué movimiento hubo de actuar Abu Bakr al comienzo de su califato?", ["La negativa a pagar el zakat y la apostasía de algunas tribus", "Una invasión desde Persia", "Una hambruna", "Una revuelta en Medina"], "El primer califato se abrió con las llamadas guerras de la ridda, contra las tribus que negaron el zakat o abandonaron el islam."),
"sira_213": ("¿Qué título adoptó 'Umar ibn al-Jattab como jefe de la comunidad?", ["Amir al-Mu'minin (príncipe de los creyentes)", "Sultán", "Malik", "Imam al-Haramayn"], "El título de amir al-mu'minin se estableció con 'Umar y lo llevaron los califas posteriores."),
"sira_214": ("¿Qué mezquita de Jerusalén fue la primera alquibla de los musulmanes?", ["La mezquita de Al-Aqsa", "La mezquita de Quba", "La mezquita del Profeta ﷺ", "La Mezquita Sagrada"], "Los musulmanes oraron primero hacia Jerusalén, antes de que la alquibla se fijara hacia la Kaaba."),
"sira_215": ("¿Cuáles son las tres mezquitas hacia las que se recomienda especialmente viajar?", ["La Mezquita Sagrada, la mezquita del Profeta ﷺ y Al-Aqsa", "Quba, Al-Aqsa y Kufa", "La Mezquita Sagrada, Quba y Damasco", "Al-Aqsa, Kufa y Basora"], "Se recomienda especialmente viajar a tres mezquitas: la Mezquita Sagrada, la mezquita del Profeta ﷺ y la mezquita de Al-Aqsa."),
"sira_216": ("¿Dónde pronunció el Profeta ﷺ su sermón de despedida, el día de 'Arafa?", ["En el valle de 'Urana, en el monte 'Arafat", "En Mina", "Ante la Kaaba", "En Muzdalifa"], "El sermón de despedida se pronunció el día de 'Arafa, en el valle de 'Urana, al pie del monte 'Arafat."),
"sira_217": ("¿Qué declaró inviolable el Profeta ﷺ en su sermón de despedida?", ["La sangre, los bienes y el honor de cada uno", "Las rutas comerciales", "Los pozos de Medina", "Los palmerales"], "Declaró sagrados la sangre, los bienes y el honor de los musulmanes, como es sagrado ese día, ese mes y esa ciudad."),
"sira_218": ("¿Qué dejó el Profeta ﷺ a su comunidad, según su sermón de despedida, para que no se extraviara?", ["El Libro de Allah", "Un tesoro", "Un ejército", "Un mapa"], "Les recordó que dejaba entre ellos aquello a lo que aferrarse para no extraviarse: el Libro de Allah."),
"sira_219": ("¿En qué mes del calendario musulmán se realiza la peregrinación, cumplida por el Profeta ﷺ en su despedida?", ["Du-l-Hiyya", "Ramadán", "Muharram", "Rayab"], "La peregrinación de despedida tuvo lugar en Du-l-Hiyya del año 10 de la Hégira."),
"sira_220": ("¿Quién lavó y amortajó el cuerpo del Profeta ﷺ tras su muerte?", ["Los de su casa, entre ellos 'Ali y al-'Abbas", "Solo los ansar", "Bilal y Anas", "La gente de Quba"], "Se encargó de ello su propia familia, entre ellos 'Ali ibn Abi Talib y su tío al-'Abbas."),
"sira_221": ("¿En qué mes del año hegiriano murió el Profeta ﷺ?", ["Rabi' al-Awwal", "Ramadán", "Shawwal", "Du-l-Qa'da"], "El Profeta ﷺ murió en Medina en el mes de Rabi' al-Awwal del año 11 de la Hégira."),
"sira_222": ("¿Qué aleya recitó Abu Bakr para recordar que el Profeta ﷺ era mortal?", ["«Muhammad no es sino un mensajero; antes de él pasaron otros mensajeros»", "«Te hemos enviado como misericordia»", "«Eres de un carácter eminente»", "«Cuando llegue el auxilio de Allah»"], "«Muhammad no es sino un mensajero; antes de él pasaron otros mensajeros. Si muriera o lo mataran, ¿volveríais sobre vuestros pasos?»"),
"sira_223": ("¿Qué compañero es conocido sobre todo por la cantidad de hadices que memorizó?", ["Abu Huraira", "Anas ibn Malik", "Yabir ibn 'Abdillah", "Abu Sa'id al-Judri"], "Abu Huraira pasó los últimos años de la vida del Profeta ﷺ a su lado y fue el transmisor más prolífico de hadices."),
"sira_224": ("¿Qué compañero, primo del Profeta ﷺ, llegó a ser la gran autoridad en exégesis coránica?", ["'Abdullah ibn 'Abbas", "'Abdullah ibn 'Umar", "'Abdullah ibn Mas'ud", "'Abdullah ibn az-Zubayr"], "'Abdullah ibn 'Abbas, por quien el Profeta ﷺ pidió la comprensión del Libro, fue llamado «el intérprete del Corán»."),
"sira_225": ("¿Qué compañero fue enviado por el Profeta ﷺ como gobernador y juez a Yemen, y murió joven en Siria?", ["Mu'adh ibn Yabal", "Abu 'Ubayda ibn al-Yarrah", "'Amr ibn al-'As", "Jalid ibn al-Walid"], "Mu'adh ibn Yabal, sabio entre los compañeros, fue enviado a Yemen y después murió en Siria siendo aún joven."),
"sira_226": ("¿Qué valle se extiende entre las dos colinas de Safa y Marwa, recorridas durante la peregrinación?", ["El valle de La Meca, alrededor de la Kaaba", "El valle de 'Urana", "El valle de Mina", "El valle de Badr"], "Safa y Marwa son dos pequeñas colinas del valle de La Meca, hoy incluidas dentro de la Mezquita Sagrada."),
"sira_227": ("¿Qué dos grandes tribus árabes de Medina se hacían la guerra antes de la llegada del Profeta ﷺ?", ["Los Aws y los Jazray", "Quraish y Hawazin", "Zaqif y Kinana", "Tamim y Bakr"], "Los Aws y los Jazray, enemigos durante mucho tiempo, formaron juntos a los ansar tras la llegada del Profeta ﷺ."),
"sira_228": ("¿Qué aleya recuerda a los ansar que eran enemigos y que Allah unió sus corazones?", ["«Erais enemigos y Él unió vuestros corazones»", "«Erais pobres»", "«Erais pocos»", "«Estabais perdidos»"], "«Recordad el favor de Allah con vosotros: erais enemigos y Él unió vuestros corazones, y por Su favor os hicisteis hermanos»."),
"sira_229": ("¿Cómo elogia el Corán a los ansar en su acogida a los emigrados?", ["Los prefieren a sí mismos, aun estando necesitados", "Les vendieron tierras", "Les prestaron dinero", "Los alojaron fuera de la ciudad"], "«Y los prefieren a sí mismos, aunque estén necesitados. Quien se guarde de su propia avaricia, esos son los triunfadores»."),
"sira_230": ("¿Cómo se llama el conjunto de dichos, actos y aprobaciones del Profeta ﷺ?", ["La Sunna", "El Corán", "La Sira", "El Tafsir"], "La Sunna es lo que el Profeta ﷺ dijo, hizo o aprobó; la Sira es el relato de su vida."),
"sira_231": ("¿Cómo se llama la generación que siguió a la de los compañeros?", ["Los tabi'un (los seguidores)", "Los ansar", "Los muhayirun", "Los qurra'"], "Los tabi'un son quienes conocieron a los compañeros sin haber visto al Profeta ﷺ."),
"sira_232": ("¿Cómo se llama la cadena de transmisores de un hadiz?", ["El isnad", "El matn", "El tafsir", "El taywid"], "El isnad es la cadena de transmisión; el matn es el texto mismo del hadiz."),
"sira_233": ("¿Cuáles son las dos colecciones de hadices tenidas por más rigurosas, llamadas «los dos Sahih»?", ["Sahih al-Bujari y Sahih Muslim", "Los Sunan de Abu Dawud y at-Tirmidi", "El Muwatta' y el Musnad", "Los Sunan de an-Nasa'i e Ibn Maya"], "Sahih al-Bujari y Sahih Muslim se conocen juntos como «los dos Sahih» (as-sahihan)."),
"sira_234": ("¿En qué ciudad se encuentran la mezquita del Profeta ﷺ y su tumba?", ["Medina", "La Meca", "Jerusalén", "Taif"], "La mezquita del Profeta ﷺ y su tumba están en Medina, la ciudad de la Hégira."),
"sira_235": ("¿Qué epíteto lleva Medina, en relación con la luz que se le atribuye?", ["Al-Madina al-Munawwara (la ciudad iluminada)", "Umm al-Qura", "Dar as-Salam", "Al-Mada'in"], "A Medina se la llama al-Munawwara; a La Meca, por su parte, al-Mukarrama."),
"sira_236": ("¿Qué nombre da el Corán a La Meca, «la madre de las ciudades»?", ["Umm al-Qura", "Al-Madina", "Al-Balad al-Amin", "Bakka"], "«…para que adviertas a la madre de las ciudades (Umm al-Qura) y a quienes están a su alrededor»."),
"sira_237": ("¿Cuál era el oficio de Jadicha, primera esposa del Profeta ﷺ?", ["Comerciante", "Médica", "Poetisa", "Tejedora"], "Jadicha bint Juwaylid era una comerciante respetada de La Meca, que confió su caravana al joven Muhammad ﷺ."),
"sira_238": ("¿Cuánto tiempo estuvo el Profeta ﷺ casado solo con Jadicha?", ["Hasta la muerte de ella; no se casó con ninguna otra en su vida", "Dos años", "Cinco años", "Se casó con otras enseguida"], "El Profeta ﷺ no se casó con ninguna otra mujer mientras vivió Jadicha; los demás matrimonios vinieron tras su muerte."),
"sira_239": ("¿Cómo se llama el tío del Profeta ﷺ que lo protegió sin abrazar el islam?", ["Abu Talib", "Hamza", "Al-'Abbas", "Abu Lahab"], "Abu Talib, padre de 'Ali, protegió a su sobrino frente a Quraish hasta su muerte."),
"sira_240": ("¿Qué tío del Profeta ﷺ fue hecho prisionero en Badr antes de abrazar el islam?", ["Al-'Abbas ibn 'Abd al-Muttalib", "Abu Talib", "Hamza", "Az-Zubayr ibn 'Abd al-Muttalib"], "Al-'Abbas, tío del Profeta ﷺ y antepasado de los abasíes, fue capturado en Badr y después abrazó el islam."),
"sira_241": ("¿Cómo se llama a los compañeros que participaron en la batalla de Badr?", ["Los badríes (badriyyun)", "Los ansar", "Los muhayirun", "Los uhudíes"], "A los compañeros presentes en Badr se los conoce como badriyyun, y ese mérito les es propio."),
"sira_242": ("¿Qué parte del botín reserva el Corán para Allah, el Mensajero, los parientes, los huérfanos, los pobres y el viajero?", ["El quinto", "La mitad", "El décimo", "El tercio"], "«Sabed que de todo botín que toméis, un quinto es para Allah, para el Mensajero, para los parientes, los huérfanos, los pobres y el viajero»."),
"sira_243": ("¿Qué aleya, unida al sermón de despedida, funda la igualdad de los pueblos ante Allah?", ["«El más noble de vosotros ante Allah es el más piadoso»", "«Los hombres vienen de un solo padre»", "«Nadie carga con la carga ajena»", "«No hay coacción en la religión»"], "«Hombres, os hemos creado de un varón y una hembra… el más noble de vosotros ante Allah es el más piadoso»."),
"sira_244": ("¿Cuántos participaron en el segundo pacto de 'Aqaba, el encuentro decisivo con la gente de Yazrib?", ["Una delegación de más de setenta personas", "Tres", "Diez", "Quinientos"], "El segundo pacto de 'Aqaba reunió a una delegación de más de setenta hombres y mujeres de Yazrib."),
"sira_245": ("¿Cuántos naqibs (responsables) hizo designar el Profeta ﷺ entre la gente de Yazrib en el pacto de 'Aqaba?", ["Doce", "Cuatro", "Siete", "Veinte"], "Se eligieron doce naqibs para representar a los grupos de la delegación de Yazrib y responder de su compromiso."),
"sira_246": ("¿Qué nombre adoptó Medina tras la Hégira?", ["Madinat an-Nabi, la ciudad del Profeta ﷺ", "Yazrib", "Solo Tayba", "Al-Qura"], "Yazrib pasó a llamarse Madinat an-Nabi, «la ciudad del Profeta ﷺ», abreviado como al-Madina."),
"sira_247": ("¿Qué califa mandó copiar el Corán en ejemplares oficiales enviados a las provincias?", ["'Uzman ibn 'Affan", "Abu Bakr", "'Umar", "'Ali"], "Abu Bakr mandó reunir el texto; 'Uzman hizo establecer copias oficiales y las envió a las grandes ciudades."),
"sira_248": ("¿En qué lengua fue revelado el Corán al Profeta ﷺ?", ["En árabe", "En arameo", "En persa", "En griego"], "El Corán fue revelado en lengua árabe clara, la del propio pueblo del Profeta ﷺ."),
"sira_249": ("¿A qué compañero envió el Profeta ﷺ a Bahréin, y volvió con su tributo?", ["Abu 'Ubayda ibn al-Yarrah", "Bilal", "Anas ibn Malik", "Abu Zarr"], "Abu 'Ubayda ibn al-Yarrah, llamado «el hombre de confianza de esta comunidad», volvió de Bahréin con su tributo."),
"sira_250": ("¿Qué acontecimiento marca el comienzo del calendario musulmán?", ["La Hégira de La Meca a Medina", "El nacimiento del Profeta ﷺ", "La primera revelación", "La conquista de La Meca"], "El calendario hegiriano comienza con el año de la Hégira, decisión tomada durante el califato de 'Umar."),
}
